record.field:
{
    "type": "object",
    "properties": {
        "product_names": {
            "type": "array",
            "description": "Product names, internal references, or barcodes requested by the user. Keep the same order as quantities.",
            "items": {"type": "string"}
        },
        "quantities": {
            "type": "array",
            "description": "Requested quantities. Keep the same order as product_names.",
            "items": {"type": "number"}
        },
        "note": {
            "type": "string",
            "description": "Optional order note from the user. Use an empty string if the user provides no note."
        }
    },
    "required": ["product_names", "quantities", "note"]
}

{
    "type": "object",
    "properties": {
        "query": {
            "type": "string",
            "description": "A product name, internal reference, barcode, or a few product and attribute keywords. Use catalog spellings when known."
        }
    },
    "required": ["query"]
}

{
    "type": "object",
    "properties": {
        "product_names": {
            "type": "array",
            "description": "Exact references or barcodes, or complete variant names copied from the website catalog search. Prefer references and preserve catalog spellings without translation. Keep the same order as quantities.",
            "items": {"type": "string"}
        },
        "quantities": {
            "type": "array",
            "description": "Positive whole-number quantities to add to cart. Keep the same order as product_names.",
            "items": {"type": "number"}
        },
        "note": {
            "type": "string",
            "description": "Optional user note. Use an empty string if the user provides no note."
        }
    },
    "required": ["product_names", "quantities", "note"]
}
